<template><section class="auth-card"><h1>{{ register ? 'Create account' : 'Welcome back' }}</h1><p class="muted">{{ register ? 'Start shopping in seconds.' : 'Sign in to continue.' }}</p><form @submit.prevent="submit"><input v-if="register" v-model="form.name" placeholder="Full name" required><input v-model="form.email" type="email" placeholder="Email" required><input v-model="form.password" type="password" placeholder="Password" required><p v-if="error" class="error">{{ error }}</p><button class="primary">{{ register ? 'Register' : 'Sign in' }}</button></form><button class="link" @click="register=!register">{{ register ? 'Already have an account? Sign in' : 'New here? Create an account' }}</button><p class="hint">Demo customer: demo@shop.local / demo123<br>Admin: admin@shop.local / admin123</p></section></template>
<script>
import { useAuthStore } from '../stores/authStore.js'
export default { data: () => ({ register: false, form: { name: '', email: '', password: '' }, error: null }), methods: { async submit() { try { const auth = useAuthStore(); this.register ? await auth.register(this.form) : await auth.login(this.form); this.$router.push('/products') } catch (e) { this.error = e.response?.data?.detail || e.response?.data?.message || 'Unable to sign in' } } } }
</script>
<style scoped>.auth-card{max-width:420px;margin:35px auto;background:white;padding:32px;border-radius:14px;box-shadow:0 10px 30px #18284812}.auth-card h1{margin-bottom:8px}.muted,.hint{color:#68738a;margin-bottom:22px}.auth-card form{display:grid;gap:12px}.auth-card input{padding:12px;border:1px solid #d5dbea;border-radius:7px;font-size:1rem}.primary{background:#536dfe;color:white;border:0;border-radius:7px;padding:12px;font-size:1rem}.link{border:0;background:none;color:#536dfe;margin-top:18px}.hint{font-size:.8rem;line-height:1.6;margin-top:22px}.error{color:#c0392b;font-size:.9rem}</style>
